        "t": "8. Civilizația romană",
        "p": "Istoria Romei începe în secolul al VIII-lea î.H., în câmpia Latium, pe malul stâng al râului Tibru. Acolo trăiau latinii și sabinii. Locul era bun pentru comerț și agricultură, pentru că pământul era roditor. Meșterii pricepuți lucrau fierul, arama, marmura și lemnul. Alpii dădeau protecție împotriva frigului și a dușmanilor. În anul 753 î.H. a fost întemeiat orașul Roma. Legenda spune că troianul Enea a ajuns în Latium, iar fiul lui, Ascaniu, a întemeiat Alba Longa. Din acest neam s-au născut Romulus și Remus, hrăniți de o lupoaică. Lupoaica a devenit simbolul Romei. După istorici, Roma a fost întemeiată la 21 aprilie 753 î.H. Istoria Romei are trei etape: epoca regală (secolele VIII–VI î.H.), republica (510–30 î.H.) și imperiul (30 î.H.–476 d.H.). Roma a avut șapte regi: sabini, latini și etrusci. Primul a fost Romulus (753–717 î.H.). Adunarea Populară, formată din patricieni (nobili), putea hotărî pacea și războiul. Senatul era cel mai important organ care făcea legile. La început a avut 100 de membri, apoi 300. În 509 î.H. patricienii erau nemulțumiți de regele etrusc Tarquinius Superbus și au proclamat Republica. Ea era condusă de doi consuli, care comandau armata și chemau Senatul. Pe vremea lui Caesar, Senatul a ajuns la 900 de membri. În 494 î.H. plebeii (oamenii de rând) au plecat din oraș, iar patricienii au cedat. Plebeii au primit tribuni, cu drept de veto (puteau opri o hotărâre). Persoana tribunilor era inviolabilă, adică nimeni nu avea voie să-i atingă. Legea celor 12 Table a fost scrisă în anii 451–449 î.H. La început a fost pe table de lemn, apoi pe table de bronz. Tablele de bronz au fost distruse în 390 î.H. de gali. Iar legea a rămas în vigoare aproximativ 1.100 de ani.",
