        "t": "9. Studiu de caz. Republica Romană",
        "p": "În anul 509 î.H. s-a născut la Roma prima republică din istorie. Ea a apărut după lupta dintre patricieni și plebei. Republica era condusă de Adunarea Populară, de Senat și de magistrați (consuli, cenzori și dictator). Puterea în stat și în armată era în mâna celor doi consuli. Ei erau aleși pentru un an, dintre patricieni. Conduceau armata, prezidau Senatul și adunările și judecau ca ultimă instanță. Purtau togă cu margini roșii și erau însoțiți de 12 lictori, care duceau pe umeri fascii, simbolul puterii supreme. Când era pericol, un dictator primea putere nelimitată timp de șase luni. Mai existau pretorii, care se ocupau de procese, cenzorii, aleși pentru cinci ani, care stabileau veniturile statului, și chestorii, care administrau averea statului. Senatul era cel mai important organ politic și avea 300 de patricieni. Plebeii erau reprezentați de tribuni, care aveau drept de veto. Republica a cucerit mult teritoriu: Italia, Cartagina și nordul Africii. Pe vremea lui Caesar (100–44 î.H.) au fost cucerite Galia, Britania și Germanicum. Triumviratul (conducerea de către trei oameni) și criza socială au dus la căderea republicii. Apoi a început  era imperiului.",
