        "t": "11. Civilizațiile străvechi în spațiul românesc și formarea traco-geto-dacilor",
        "p": "Teritoriul României de azi se afla în calea multor popoare care se mutau dintr-un loc în altul. De aceea, culturile de aici se schimbau des. Culturile Boian, Gumelnița, Hamangia, Noua și Monteoru arată progrese în felul de a lucra și în economie și o populație tot mai numeroasă. Cultura Horodiștea-Erbiceni și-a luat numele de la localități din județul Botoșani și de lângă Iași. Ea s-a răspândit în nordul Moldovei. În Republica Moldova i se spune Brânzeni-Gordinești. Ea continuă ceramica pictată a culturii Cucuteni, dar cu decor mai simplu, făcut cu șnurul. Mormintele erau plane, nu sub movilă. Tracii sunt pomeniți pentru prima dată în poemele lui Homer, în războiul Troiei. Ei erau aliații troienilor și erau conduși de regele Rhesos. Aveau cai vestiți, arme deosebite și un car acoperit cu aur și argint. Obiecte asemănătoare din metal prețios s-au găsit în județele Dâmbovița, Sibiu, Neamț, Cluj și Satu Mare. În mileniul al III-lea î.H., în zona Carpaților, a Dunării și a Mării Negre trăiau tracii, un popor indo-european. Poporul trac s-a format din două grupuri. Primul grup era format din agricultorii care trăiau deja aici. Al doilea grup erau păstorii indo-europeni veniți din stepă. Păstorii și-au impus limba, dar au fost asimilați de localnici. Herodot scria că, după indieni, tracii sunt cel mai numeros popor. El spunea că, dacă ar fi uniți, nimeni nu i-ar învinge. Triburile tracilor se întindeau până la Marea Baltică în nord și până la Munții Balcani în sud.",
