        "t": "12. Sinteză analitică. Geto-dacii și lumea greacă",
        "p": "Marea colonizare greacă a ajuns în zona Carpaților, a Dunării și a Mării Negre încă din a doua jumătate a secolului al VIII-lea î.H. Corăbierii din Eubeea au trecut prin Marea Egee, Dardanele, Marea Marmara și Bosfor. Mai târziu, ionienii din Milet au întemeiat 90 de așezări. Ei au făcut din Marea Neagră (Pontul Euxin) un „lac al Miletului”. Printre locurile colonizate sunt Leuke (Insula Șerpilor), Tyras, Histria, Olbia, Tomis și Apollonia. Amforele cu vin și ulei, stofele scumpe, armele și bijuteriile grecești ajungeau departe în țara dacilor. Geto-dacii vindeau grâne, lemn, blănuri, pește, miere și ceară. Grecii erau cinstiți în comerț. Produsele lor erau bune, iar când marfa localnicilor valora mai mult, ei dădeau diferența înapoi. La început geto-dacii nu aveau monedă proprie. Ei au făcut monede după modelul drahmei grecești. Nobilii au început să poarte mantii din stofă grecească. Oamenii de rând au câștigat și ei din comerț, pentru că ei făceau mărfurile căutate de greci. Vasile Pârvan spunea că, în jurul anului 500 î.H., Dunărea până la Siret era „o apă grecească”. Către secolul al IV-lea î.H., căpeteniile geților au luat de la greci ideea Adunării Populare. În jurul anului 300 î.H., regele Dromihete a chemat Adunarea ca să hotărască soarta lui Lisimah. Regele Mosconos apare în izvoare cu titlul de „basileos” (rege). Influența greacă a ajutat la formarea uniunilor de triburi și a adus și robia. Perioada secolelor VIII–II î.H. se numește etapa elenistică a geto-dacilor.",
