        "t": "1. Modele de organizare politică în lumea antică: de la orașe-state la imperii",
        "p": "Statul a apărut în Antichitate pentru că oamenii aveau nevoie de ordine, de apărare și de cineva care să organizeze munca, economia și credințele. În Orientul Antic au existat trei forme de organizare: orașul-stat, regatul și imperiul. Orașul-stat este cea mai veche formă. El se formează în jurul unui oraș central. A apărut în sudul Mesopotamiei, în mileniul IV î.H., la sumerieni (Ur, Uruk, Eridu, Nippur, Lagaș) și la akkadieni (Kish, Akkad). Regele era ajutat de nobilii din oraș. El era preot, judecător suprem și conducătorul armatei. Orașe-state au avut și fenicienii (Ugarit, Sidon, Tyr). În secolul al X-lea î.H., orașul Tyr a făcut o alianță cu alte orașe feniciene și a întemeiat colonii. Cea mai cunoscută este Cartagina. Pe insula Creta, orașele Cnossos, Phaistos și Zakros erau centre de cultură. Polisul era orașul-stat al grecilor. El a apărut în secolele IX–VI î.H., iar Solon este cel care a pus bazele ideii de polis. Regatul are în frunte un rege, pe viață. Unele regate s-au format din orașe-state care s-au impus altora (Sumer, Akkad, Babilon). Altele s-au format din uniuni de triburi (Egipt, India, China, Persia). În Egipt, Regatul Nou se mai numește și Imperiu. Faraonul Tutmes al III-lea a cucerit Palestina, Siria, Fenicia și Etiopia. Ramses al II-lea a fost un mare constructor. Amenhotep al IV-lea a impus cultul zeului Aton. În 525 î.H. Egiptul a fost cucerit de persani. Hammurabi a condus Babilonul timp de 42 ani. Codul său are 282 de articole, pe o piatră foarte tare, și a fost folosit o mie de ani. Burebista a unit triburile geto-dace, a avut centrul în zona Orăștiei și capitala la Sarmizegetusa și a cucerit orașele grecești de la Marea Neagră. Imperiul a adunat, prin forța armelor, mai multe regate și popoare sub o singură conducere. Cele mai cunoscute imperii au fost Maurya, cel Persan, cel Macedonean și cel Roman. Imperiul Maurya avea capitala la Pataliputra. În 265 î.H. se întindea pe 5 milioane de km².",
