        "t": "2. Modele de organizare politică în Grecia Antică",
        "p": "În Grecia Antică au existat mai multe forme de conducere: monarhii, regate și polisuri. Unele polisuri erau democratice, ca Atena. Altele erau aristocratice, ca Sparta. Polisurile au apărut în secolele VIII–VI î.H. Mai întâi au fost pe coasta Asiei Mici (Milet, Efes). Apoi au apărut în Grecia propriu-zisă (Atena, Sparta, Teba, Corint, Megara). Polisul era un oraș-stat, iar cine făcea parte din el avea drepturi, avere și siguranță/protecție. În polisurile conduse de un rege, regele era și preot, și comandant al armatei, și judecător suprem. Mai târziu au luat puterea aristocrații, adică oamenii bogați. În secolul al VII-lea î.H. ei au fost dați la o parte de tiran. Tiranul era sprijinit de popor, dar ajungea la putere prin forță. Oligarhia era conducerea unui grup mic de oameni bogați. În democrație, toți cetățenii (bărbații) făceau legile și conduceau statul. Străinii, femeile și sclavii nu aveau drepturi politice. Atena, capitala Aticii, este considerată locul în care s-a născut democrația. Adunarea Poporului se numea Ecclesia. Din ea făceau parte bărbații născuți în polis, care aveau 20 de ani împliniți. La început se adunau în Agora, apoi pe colina Pnyx. Acolo orice cetățean putea ține un discurs. Democrația a ajutat la apariția unor mari oratori (oameni care vorbeau foarte bine în public): Demostene, Isocrate și Pericle. Prin ostracism, un cetățean bănuit că vrea să ia puterea era trimis din Atena pentru zece ani. El își păstra însă bunurile. În 417 î.H. ostracismul a fost înlocuit cu paranomon graphe.",
