        "t": "4. Studiu de caz. Atena și Sparta, polisuri cu sistem politic specific",
        "p": "Sparta a fost întemeiată de dorieni în mileniul I î.H. Ei au unit cinci cetăți din câmpia Laconiei, în sud-estul Peloponezului. În secolele VIII–VII î.H. spartanii au stăpânit toată peninsula. Ei se numeau homoioi („egalii”), iar locuitorii cuceriți au fost făcuți sclavi și se numeau iloți. Regimul era aristocratic. După tradiție, el a fost pus la punct de legiuitorul Licurg. Sparta avea doi regi cu atribuții în război, un Sfat al bătrânilor (Gerusia), Adunarea Poporului (Apella) și Colegiul celor cinci efori, care avea puterea de a face ca legile să fie respectate. „Egalii” nu munceau. Agricultura era treaba iloților. Perieci erau oameni liberi, dar fără cetățenie, și lucrau ca meșteșugari. Spartanii se ocupau mai ales cu războiul. Bărbații între 12 și 60 de ani făceau în fiecare zi antrenament militar. Armata lor era cea mai puternică din Grecia. Atena a fost întemeiată de triburi ioniene. În societatea ei erau eupatrizii (nobilii), demosul (oamenii de rând) și metecii (străini fără drepturi politice). În secolul al VII-lea î.H. puterea era la aristocrația eupatrizilor, cu nouă arhonți și cu Areopagul, care făcea dreptate. Legile lui Dracon din 621 î.H. au pus limite abuzurilor. Democratizarea a început cu Solon, în 594 î.H., iar Clistene a introdus ostracismul. Adunarea Poporului avea 40.000 de cetățeni. Ea hotăra pacea și războiul și alegea magistrații prin tragere la sorți. Legile erau pregătite de bulé, un consiliu cu 500 de membri. În secolul al V-lea î.H. Atena avea 420.000 de locuitori. Circa 220.000 dintre ei erau sclavi. De aceea, foarte puțini aveau drepturi de cetățeni.",
