        "t": "6. Studiu de caz. Elenismul",
        "p": "Alexandru Macedon a murit în 323 î.H., fără urmaș. Imperiul a fost împărțit între generalii lui, numiți diadohi, adică „urmași”. Fiii și nepoții lor se numesc epigoni. Elenismul este civilizația în care obiceiurile grecești s-au amestecat cu cele din Orient. S-a născut după întemeierea Imperiului Macedonean. Perioada elenistică ține din anul morții lui Alexandru până în 30 î.H., când s-a sinucis Cleopatra, ultima regină a Egiptului elenistic. Micile polisuri au fost înlocuite de state uriașe, ca întindere și număr de locuitori. Centrul lumii grecești s-a mutat în Egipt și Asia Mică. Diadohii   s-au luptat pentru putere peste 40 de ani. În 281 î.H. existau patru state principale: Macedonia, Siria, Egipt și Anatolia. În 283 î.H. Philetaerus a întemeiat Regatul Atalizilor din Pergam. Acolo s-a construit Altarul din Pergam și a fost inventat pergamentul, când nu mai veneau papirusuri din Egipt. În Egipt, Ptolemeu I Soter a întemeiat o dinastie. El fusese prieten cu Alexandru și îi scrisese viața. A înființat Museionul, Serapeionul (templul zeului Serapis) și Marea Bibliotecă din Alexandria. Fiul lui a construit Farul din Alexandria, una dintre cele șapte minuni ale lumii antice. Alexandru însuși a încurajat amestecul culturilor. A sprijinit căsătoriile dintre greci și orientali. A păstrat obiceiurile popoarelor cucerite. În Egipt s-a proclamat faraon, apoi zeu. Epoca elenistică s-a încheiat când romanii au cucerit Egiptul.",
