        "t": "7. Forme de organizare politico-statală în Roma Antică",
        "p": "Statul roman a avut trei forme: regat, republică aristocratică și imperiu. Imperiul a fost de două feluri: principat și dominat. Istoria Romei durează 12 secole. Începe în 753 î.H. și se încheie la 4 septembrie 476, când a căzut Imperiul Roman de Apus. Roma regală a durat între 753 și 509 î.H. A avut șapte regi, de la Romulus până la Tarquinius Superbus. Regele era comandant al armatei și mare preot. Puterea lui era limitată de Senat (numele vine de la senex, „bătrân”) și de Adunarea Poporului. Societatea era împărțită în patricieni și plebei. Patricienii erau proprietari de pământ și aveau toate drepturile politice. Plebeii erau oameni liberi, dar fără drepturi civile. În 509 î.H. regele a fost alungat. Timp de aproape 500 de ani, Roma a fost republică (res publica). Ea era condusă de Senat, de magistrați și de Adunările Poporului, numite comiții. Plebeii au câștigat lupta cu patricienii. În jurul anului 450 î.H. a fost scris primul cod roman de legi, Cele 12 Table. Ele au fost expuse în Forum și garantau egalitatea între patricieni și plebei. În fruntea magistraților stăteau doi consuli, aleși în fiecare an. Senatul avea 300 de membri. La început erau doar patricieni, mai târziu și plebei. Sclavii, femeile și copiii nu aveau drepturi politice. Între secolele V și III î.H. armata romană a supus popoarele din Italia. Apoi Roma a purtat războaie cu Cartagina și cu Macedonia. Criza din secolele II–I î.H. și primul Triumvirat (Caesar, Pompei și Crassus) au dus la sfârșitul republicii. Caesar a devenit dictator pe viață și a fost ucis la 15 martie 44 î.H. Octavian a câștigat lupta pentru putere la Actium, în 31 î.H. În 27 î.H. Senatul i-a dat titlul de Augustus („slăvitul”) și pe cel de princeps („cel dintâi cetățean”). Imperiul a durat aproape 500 de ani.",
