        "t": "9. Portret istoric. Cleopatra a VII-a, regina Egiptului",
        "p": "Cleopatra a VII-a Philopator a fost ultimul faraon al Regatului Ptolemeic din Egipt. Dinastia ei venea de la Ptolemeu I Soter, un general al lui Alexandru Macedon. Cleopatra s-a născut în 69 î.H. Numele ei înseamnă „gloria tatălui”. A avut o educație aleasă. Vorbea șapte limbi (printre ele latina, aramaica, araba și egipteana) și știa astronomie, medicină, filozofie, diplomație și istorie. Tatăl ei a murit în 51 î.H. Atunci ea avea 18 ani și fratele ei, Ptolemeu al XIII-lea, 10 ani. Au fost numiți împreună conducători ai Egiptului. Rivalitatea dintre ei a dus la un război civil. În octombrie 48 î.H. Caesar a cunoscut-o pe Cleopatra și a ajutat-o. Ea a rămas singura conducătoare, iar Caesar și-a asigurat grâul egiptean pentru Roma. În iunie 47 î.H. Cleopatra a născut un băiat, Cezarion. Ea spunea că el este fiul lui Caesar. După uciderea lui Caesar, ea l-a cucerit pe Marcus Antonius, unul dintre triumviri. Relațiile dintre Octavian și Antonius s-au stricat, iar Octavian a declarat război Cleopatrei. Bătălia navală de la Actium, din septembrie 31 î.H., a fost câștigată de Octavian. În 30 î.H. Cleopatra s-a sinucis, probabil lăsându-se mușcată de un șarpe veninos. În testament cerea ca Cezarion să conducă Egiptul. Octavian l-a executat, iar Egiptul a devenit provincie romană.",
