        "t": "10. Apariția statului la geto-daci. Dacia pe timpul lui Burebista",
        "p": "Acum aproximativ patru mii de ani, tracii, un popor indo-european, s-au așezat pe ambele maluri ale Dunării. Dintre triburile lor, doar odrisii și geto-dacii și-au făcut state. Geto-dacii trăiau într-un loc bun. Aveau munții Carpați, cu păduri de brad și minereuri, pășuni, dealuri, câmpii roditoare, ape pline de pește și țărmul Mării Negre. Societatea lor avea două grupuri. Tarabostes (sau pileații) erau nobilii, care purtau pe cap o căciulă numită pileus. Comati (sau capillati) erau oamenii liberi, cu părul lung și cu un trai mai simplu. Geto-dacii cultivau cereale și viță-de-vie, creșteau vite și albine, făceau ceramică, lucrau lemnul și metalele. Făceau comerț cu grecii, cu romanii și și-au bătut propria lor monedă. Herodot scria că geții sunt cei mai curajoși și mai drepți dintre traci. El spunea că ei cred că cel care moare merge la zeul Zalmoxis. Un regat al geților a fost cel al lui Dromihete, în sudul Moldovei. Izvoarele mai amintesc de formațiuni conduse de Rex Histrianorum, Zalmodegikos și Rhemaxos. În secolul al II-lea î.H. statul roman se apropia de Balcani, iar celții erau o primejdie dinspre vest. De aceea geto-dacii s-au unit în anul 82 î.H. sub conducerea lui Burebista. El a fost ajutat de marele preot Deceneu și a făcut din Dacia un stat puternic la nord de Dunăre. Capitala era la Sarmizegetusa, în Munții Orăștiei. Acolo a construit un lanț de cetăți de apărare, numite dave. După modelul grecilor, a creat un Consiliu al principilor. Legile lui se numeau belagines („legi frumoase”). Strabon spune că regele avea o armată de 200.000 de oameni. Autorii antici cred că statul lui Burebista avea în jur de un milion de locuitori. Iar Burebista moare în anul 44 î.H.",
