        "t": "11. Studiu de caz. Scrierile greceşti şi romane despre civilizaţia traco-geto-dacică şi conducătorii politici",
        "p": "Geto-dacii făceau parte din triburile tracice, din marea familie indo-europeană. S-au deosebit de alte triburi la sfârșitul primei epoci a fierului. Sunt pomeniți ca neam în izvoare scrise încă din secolul al VI-lea î.H. Herodot scria că tracii sunt cel mai numeros popor, după indieni. Spunea că, dacă ar avea un singur conducător, nimeni nu i-ar putea învinge. El a mai scris că geții „se cred nemuritori”. Din cauza acestei credințe, ei se luptau cu dușmanul altfel decât alții. Strabon spunea că dacii vorbesc aceeași limbă ca geții. Arheologia arată și ea că lucrurile făcute de ei sunt asemănătoare. Despre cum arătau scriu Strabon, Galenus, Ovidiu și Horațiu. Strabon spune că coralii, un neam getic, erau blonzi, cu ochi albaștri. Ovidiu îi descrie pe geți blonzi, cu plete și barbă. Horațiu, în Ode, îi numește de mai multe ori „aspri”. Putem să ne imaginăm cum arătau și din imaginile de pe Columna lui Traian, de pe monumentul de la Adamclisi și de pe Arcul lui Constantin cel Mare. În cele 124 de scene de pe Columnă, dacii sunt puternici, înalți sau de înălțime mijlocie. Au fața scurtă și lată, nasul scurt și drept și părul drept sau ușor ondulat. Unii poartă pileus, alții au capul descoperit. Izvoarele au păstrat puține nume de regi. În jurul anului 200 î.H. apare Oroles, care lupta împotriva bastarnilor. După mijlocul secolului al II-lea î.H. apare regele Rubobostes, sub care puterea dacilor a crescut.",
