        "t": "12. Fărâmițarea statului dac și refacerea unității pe timpul lui Decebal",
        "p": "Burebista a murit pe neașteptate, în 44 î.H. Unii conducători locali voiau să se despartă de stat. Din această cauză, statul dac s-a rupt mai întâi în patru regate, apoi în cinci. Strabon scrie că Burebista a fost răsturnat de niște răsculați. Istoricul Hadrian Daicoviciu spune că nobilii nu voiau să-și piardă libertatea și privilegiile. În zona Munților Orăștiei a preluat conducerea marele preot Deceneu. El a continuat reformele lui Burebista și i-a învățat pe oameni „să asculte de porunci”. Statul lui era teocratic, adică condus de preoți. În vremea lui s-a construit Marele Sanctuar circular din Sarmizegetusa. El arată că dacii cunoșteau astronomia. Deceneu a murit în 27 î.H. După el a fost venerat Comosicus, socotit rege, mare preot și judecător suprem. El a trăit pe vremea împăraților Augustus și Tiberiu. În anii 20 d.H. a urcat pe tron Scorilo. El a condus Dacia 40 de ani și a evitat războaiele cu romanii. În vremea lui, Dacia a devenit stat laic (nu mai era condus de preoți). Unii cercetători cred că el a fost tatăl lui Decebal. Duras, probabil fratele lui Scorilo, a condus dacii în anii 87–88 d.H. Apoi i-a dat tronul nepotului său, Decebal. Vasile Pârvan arată că, pe vremea lui Decebal, dacii aveau cetăți puternice și mașini de război după modelul roman. Dar armata era în mare parte formată din țărani.",
