        "t": "13. Dacia și Imperiul Roman: războaiele daco-romane",
        "p": "În anul 89, printr-un tratat de pace, Decebal a devenit „rege prieten al poporului roman” (rex amicus populi Romani). A primit ingineri romani pentru cetăți, ajutor militar și 8 milioane de sesterți pe an. Dacia avea bogății: aur, argint, minereu de fier, pământ roditor și păduri. Ele puteau scoate Roma din criza economică. În plus, civilizația dacilor era destul de dezvoltată și îi încurca pe romani. Imperiul avea și interese militare la Dunăre. În anul 98 a devenit împărat Traian (98–117). El a hotărât să cucerească Dacia. Prima campanie a început în mai–iunie 101, cu Traian în fruntea armatei. Romanii au trecut Dunărea din Moesia Superior prin Banat, spre Sarmizegetusa, și au câștigat bătălia de la Tapae. Decebal s-a aliat cu sarmații, roxolanii și bastarnii. În iarna 101–102 a atacat trupele romane din Dobrogea și din Moesia Inferior. Traian a răspuns cu o luptă sângeroasă, la Adamclisi. În 102 Decebal a cerut pace. Traian a pus condiții grele. Teritoriile din sud și sud-est rămâneau ocupate de romani. Decebal trebuia să returneze armele și meșterii primiți în anul 89. Zidurile cetăților trebuiau dărâmate. În timpul armistițiului, Traian l-a pus pe arhitectul Apolodor din Damasc să construiască un pod de piatră peste Dunăre. Decebal și-a refăcut armata și i-a atacat pe iazigi, aliații romanilor. Senatul l-a declarat dușman al Romei. În vara anului 105 Traian a trecut Dunărea și a atacat Dacia din cinci direcții. Au căzut cetățile de la Costești, Blidaru și Piatra Roșie, iar Sarmizegetusa Regia a fost încercuită. În 106, când Decebal a văzut că riscă să fie prins, și-a luat viața, iar Dacia a devenit provincie romană.",
