        "t": "14. Patrimoniu istoric. Monumente ale gloriei romane",
        "p": "Victoria lui Traian asupra dacilor a fost sărbătorită prin monumente celebre. Columna lui Traian din Roma are circa 40 de metri. Este cel mai impresionant monument triumfal din Antichitate. A fost numită „certificatul de naștere al poporului român”. Are patru părți: fundația, piedestalul, coloana și statuia împăratului. În 1587, papa Sixtus al V-lea a înlocuit statuia împăratului cu cea a sfântului Petru. Cele peste 120 de scene arată respect față de dacii învinși într-o luptă inegală. Tropaeum Traiani de la Adamclisi a fost construit din porunca lui Traian, ca să amintească victoria din anul 106. A fost inaugurat la 12 mai 113. Monumentul are ca model mausoleul lui Octavian Augustus. Trofeul are două fețe, este înalt de 10,75 metri și înfățișează o armură cu patru scuturi. În apropiere sunt un mausoleu și un altar funerar cu numele a peste trei mii de soldați romani morți. Podul lui Traian peste Dunăre, lângă Drobeta-Turnu Severin, a fost construit de Apolodor din Damasc, arhitectul Columnei. A fost gata în mai puțin de doi ani. Avea 1.134 de metri lungime și 14,5 metri lățime. Pe el au trecut soldații și proviziile pentru a doua campanie împotriva lui Decebal. La capete avea arcuri de triumf, după cum scria Procopius din Cezareea.",
