        "t": "15. Minicercetare. Politici imperiale pentru romanizarea geto-dacilor",
        "p": "Romanizarea este un proces lung și greu. El a fost organizat și susținut de statul roman. Prin el, popoarele cucerite au preluat felul de administrare al imperiului, legile, limba latină, felul de viață, cultura și obiceiurile romanilor. Zona dintre Dunăre și Balcani a intrat în lumea romană în secolul al II-lea î.H. În 106 romanii au cucerit Dacia. Pentru ca romanizarea să reușească, teritoriul cucerit trebuia să rămână în imperiu două-trei generații. Asimilarea trebuia să se facă pașnic, iar localnicii trebuiau să fie dispuși să preia lucruri noi. Romanizarea a avut trei etape: etapa preliminară (secolul al II-lea î.H.–106), etapa activă (106–275) și etapa postromană (275–până în secolul al V-lea). Au contribuit administrația, armata, coloniștii, veteranii, orașele, economia, legile, religia și cultura. Prin aculturație (preluarea obiceiurilor altor oameni), geto-dacii au învățat minele, podurile, apeductele, administrația, legile și viața în orașe. Dacia era provincie imperială și era condusă direct de împărat, prin guvernator, cu titlul de legatus augusti. A fost împărțită în trei părți: Dacia Superior, Dacia Inferior și Dacia Malvensis. Legiunile răspândeau limba latină și dreptul roman. După 25 de ani de serviciu, veteranii se stabileau în provincii și se căsătoreau cu localnice. După anul 200, dacii au putut să intre în cohortele romane. Orașele aveau forum, temple, terme și monumente, ca la Roma. Zeii romani și creștinismul au ajutat și ele la romanizare. După retragerea aureliană din 275, romanizarea nu s-a oprit. Dovezi că dacii au continuat să trăiască aici sunt așezările de la Capidava și Șura Mică și cimitirele de la Locusteni și Enisala.",
