        "t": "1. Viața economică în lumea antică. Forme de proprietate. Economia geto-dacilor",
        "p": "Majoritatea popoarelor antice s-au format lângă râuri. Acolo se putea face agricultură, care era baza economiei. În Orient se cultiva pământul în văile Nilului, Tigrului, Eufratului, Indusului, Gangelui și Huanghe-ului. Productivitatea (cât se recolta) a crescut datorită uneltelor mai bune, muncii mai bine organizate și sistemelor de irigare (diguri, canale, lacuri pentru apă). Statele din Orient vindeau multe cereale: grâu, orez, mei și susan. În China era importantă și creșterea viermilor de mătase. În Grecia și la Roma, economia păstra unele trăsături naturale, adică oamenii produceau mai ales pentru ei. Pentru că se folosea mult munca sclavilor, economia a devenit sclavagistă. Grecii aveau puțin pământ bun, așa că lucrau intensiv, adică scoteau cât mai mult dintr-o suprafață mică. În Italia erau suprafețe mai mari, iar agricultura era extensivă, adică se lucrau terenuri întinse. La început, popoarele din Orient aveau proprietate comună. În mileniul al III-lea î.H. s-a dezvoltat proprietatea privată. Din cauza ei, societatea s-a împărțit în clase sociale. Economia naturală s-a restrâns și s-a extins comerțul cu mărfuri. Banii au circulat mai mult și au apărut primele instituții de credit. Dacii sunt unul dintre cele mai vechi popoare europene care au făcut agricultură. Ei au continuat modul de viață al celor care trăiau aici în Neolitic. Au folosit brăzdarul de fier încă din prima jumătate a secolului al IV-lea î.H. Păstoritul a rămas o ocupație de bază și în secolul I d.H. Dacii cultivau orz, secară, linte, bob și mai multe feluri de grâu. Foloseau plugul cu brăzdar și cuțit de fier, coase lungi, seceri, sape, cosoare pentru viță-de-vie, securi și greble.",
