        "t": "4. Organizarea socială la geto-daci",
        "p": "Societatea geto-dacă era patriarhală (în ea cuvântul bărbaților din familie conta cel mai mult). Ea era dominată de un grup privilegiat de războinici și preoți. Încet-încet   s-au format două grupuri principale: nobilii, care erau liberi, și producătorii liberi, care munceau în agricultură, la creșterea animalelor și în meșteșuguri. În fruntea societății era regele. La sfârșitul secolului I î.H., în vremea lui Deceneu, regele era și mare preot și locuia la Sarmizegetusa. Nu se știe dacă regele moștenea tronul. Puținele izvoare arată o democrație militară, în care regele era unul dintre comandanții armatei. Printre cei mai influenți oameni erau preoții. Ei slujeau în templele din cetăți sau de lângă ele. În unele perioade, preoții și regele erau atât de apropiați, încât statul era teocratic. Pe Columna lui Traian apar multe scene cu oameni din diferite grupuri sociale. Preoții sunt desenați ca niște bătrâni cu păr alb și lung, cu barbă și haine albe. Dar această imagine este închipuită. Nobilii se numeau tarabostes sau pileați, după căciula pileus. Din aristocrație făceau parte războinicii din armată. Ei stăpâneau cetăți sau turnuri-locuință și se ocupau de administrație, de strângerea taxelor și de judecăți. Cei mai importanți participau probabil la sfaturile regelui. Acolo se discuta despre politica din țară și din afară și despre pregătirea campaniilor. Femeile dace apar pe Columnă cu cămașă încrețită, fustă și uneori o manta lungă. Părul lor este acoperit cu o basma.",
