        "t": "5. Modul de viață în Epoca Antică",
        "p": "În orașele-state antice, modul de viață s-a schimbat puțin, timp de multe secole. Oamenii locuiau în case pentru o singură familie, mai mari sau mai mici, după cât de bogați erau. În Grecia, casele, clădirile publice și templele erau așezate în jurul agorei. Acolo se adunau oamenii ca să stea de vorbă sau să cumpere mâncare. În Atena locuiau mai mulți oameni în afara orașului decât în oraș. Casele grecești erau simple. Dormitoarele, cămările și bucătăria erau în jurul unei curți interioare. Nu aveau băi. Familia era formată din părinți și copii. Tatăl aducea banii în casă. Mama conducea sclavii, care aduceau apă, gătea, făceau curățenie și aveau grijă de copii. Tatăl avea o cameră separată pentru oaspeți, pentru că bărbații veniți în vizită nu aveau voie să intre în camerele femeilor și ale copiilor. Oamenii bogați făceau simpozioane (ospețe cu discuții), petreceri și cine. Mobila era puțină: scaune, mese și paturi. Sparta avea un mod de viață aparte. Scopul era să crească soldați puternici. Băieții plecau de acasă la 7 ani și trăiau în barăci. La 12 ani începea pregătirea fizică și morală. După căsătorie, bărbații nu aveau voie să locuiască cu soția până la 30 de ani. În Egipt, oamenii săraci locuiau în case din lut amestecat cu paie, cu acoperiș din frunze de palmier. Casele nobililor erau mai solide. Aveau mobilă din lemn scump, covoare și vase din sticlă colorată. În Mesopotamia, templele erau luxoase. Se construia cu argilă și piatră, iar pereții erau foarte groși, de până la 20 de metri. La Roma, patricienii locuiau în case cu o singură încăpere, numită atrium. Mai târziu au adăugat o curte și mai multe camere.",
