        "t": "6. Minicercetare. Viața de familie în Epoca Antică",
        "p": "Familia este grupul de bază al societății. În familie copiii sunt crescuți, se învață valorile și sentimentele și se păstrează legătura între generații. Familiile de azi sunt diferite de cele din Antichitate. Ea trebuie să aibă limite clare în timp și în spațiu: Orientul, nordul Africii, zona Balcanilor și Peninsula Italică. În multe familii antice tatăl avea autoritate absolută. Avea drept de viață și de moarte asupra soției și copiilor. Îi putea bate, omorî sau vinde ca sclavi. Încet-încet aceste drepturi au dispărut. În secolul I, soția romană a ajuns să fie respectată. Fetele mergeau la școală împreună cu băieții. Ele învățau literatura latină și greacă, muzica și dansul. După căsătorie, femeia putea să iasă singură la cumpărături sau în vizită și își însoțea soțul la ospețe. Căsătoria se făcea cu ritualuri și ceremonii. Principalele erau semnarea contractului și unirea mâinilor mirilor. Ele s-au păstrat până azi. În Grecia, femeia nu avea voie să participe la viața publică. Trăia într-o parte separată a casei și făcea doar treburi casnice. Băieții mergeau la școală de la șapte ani. Învățau gramatică, matematică, muzică, poezie și istorie. La gimnaziu făceau sport, pentru că grecii prețuiau întrecerea și grija pentru corp. Fetele se măritau de obicei la 14–15 ani. Căsătoria o hotărau părinții, iar scopul ei era să aibă copii, mai ales băieți. În lumea greacă, cei care nu se căsătoreau erau disprețuiți. La Sparta ei erau chiar pedepsiți prin lege. ",
