        "t": "7. Modul de viață al geto-dacilor",
        "p": "Geto-dacii trăiau pe pământuri roditoare. Se străduiau mult să alterneze culturile,    să-și îmbunătățească uneltele și să lucreze bine pământul. Casele din zonele de munte erau la suprafața solului, din lemn lipit cu lut. Multe însă erau îngropate, total sau parțial. Lemnul era materialul principal. Se mai foloseau piatra, lutul, osul, cornul, bronzul, argintul, aurul și fierul. Cei săraci locuiau în colibe din nuiele lipite cu lut sau în bordeie cu acoperiș din paie, stuf sau șindrilă. Casele celor bogați erau din bârne, cu temelie de piatră, uneori cu etaj. Aveau acoperiș din șindrilă sau țigle și uși mari cu ținte de fier. Prin contactul cu grecii, viața geto-dacilor s-a schimbat. Din Histria, Tomis și Callatis ajungeau la ei ceramică, vin grecesc, țesături, ulei, parfumuri ș.a. Nobilii beau vin din Thasos sau Chios. Nobilii din sudul Munteniei și șefii de trib din Moldova cumpărau amfore și boluri din Chios, Thasos și Lesbos. Meșterii geto-daci erau foarte buni la coifuri, pocale și cnemide (apărători pentru picior). Grecii îi lăudau pentru bijuteriile fine și brățările din aur și argint. Meșteri greci s-au stabilit în orașele geto-dace și au avut ucenici. Printre obiectele de ceramică se remarcă ceașca dacică și farfuria cu picior înalt. Foarte puțini geto-daci știau să scrie și să citească: preoții, funcționarii cancelariei regale, constructorii și șefii de ateliere.",
