        "t": "8. Civilizaţia traco-geto-dacică – parte componentă a civilizaţiei europene",
        "p": "Civilizația traco-geto-dacă s-a format în mileniul al IV-lea î.H. Ea a făcut parte din schimbările care au cuprins Europa în mileniile IV–I î.H. În mileniul I î.H., corăbierii greci din Eubeea au trecut prin Marea Egee, Hellespont, Propontida și Bosfor și au vândut mărfuri pe țărmurile Mării Negre. Au urmat ionienii și milesienii, care au întemeiat mai multe polisuri în zona geto-dacilor. Histria a fost înființată de Milet. Este cea mai veche colonie de pe coasta de vest a Mării Negre. A fost întemeiată în 657 î.H., după Eusebiu. Originea ei milesiană este confirmată de Pliniu cel Bătrân și de Strabon. Tomis este tot o colonie a Miletului. Callatis este singura colonie întemeiată de dorieni, după Pseudo-Scymnos și Pliniu cel Bătrân. Cele trei colonii nu s-au dezvoltat la fel, dar au avut multe lucruri comune. Traco-geto-dacii trăiau într-un spațiu foarte întins, în estul Europei. Ei aveau legături militare, economice, politice și culturale. Acestea se făceau prin comerț, apărare sau atac. Zona dintre Carpați și Nistru se află la întâlnirea Europei Centrale, de Est și de Sud-Est. De aceea au fost multe migrații și schimburi între comunități. Granițele naturale (Carpații, Marea Neagră și Dunărea) au ajutat la comerțul pe continent. Prin aceste legături, traco-geto-dacii au intrat în istoria scrisă. Grecii îi admirau pentru arme, cai, bijuterii, felul lor războinic și credința în nemurire.",
