        "t": "1. Cultura antică: scrisul, literatura, mitologia, filozofia, știința, arta",
        "p": "În Antichitate s-au dezvoltat foarte mult cultura, arta, știința și religiile marilor civilizații. Cu ajutorul lui s-au păstrat scrieri importante. Cu ajutorul lui, comunitatea își păstra amintirile. Scrierea sumeriană se numește cuneiformă. A apărut în prima jumătate a mileniului al IV-lea î.H. și a fost folosită timp de trei mii de ani. Din 3500 î.H. s-a dezvoltat scrierea egipteană hieroglifică, în care lucrurile erau arătate prin desene. Scrierea chineză a apărut în mileniul al II-lea î.H. Oamenii scriau pe piatră, lemn, tăblițe de lut, bambus, papirus, mătase și hârtie. Hârtia a fost inventată de chinezi, în jurul anului 105 d.H. Scrierea cu litere (alfabetică) este atribuită fenicienilor. În secolul al VII-lea î.H. grecii au luat alfabetul fenician. El a stat la baza alfabetului etrusc și a celui latin. Literatura antică cuprinde imnuri care slăveau zeii și regii (imnurile egiptene, Vedele indiene, Psalmii lui David), scrieri morale și mituri despre crearea lumii, despre zei, nemurire și eroi (Teogonia lui Hesiod, Biblia, Epopeea lui Ghilgameș, Mahabharata și Ramayana, Iliada și Odiseea). Literatura Greciei Antice vorbește despre mituri, epopei, tragedii și filozofie. Iliada și Odiseea, atribuite lui Homer, îi poartă pe cititori alături de Ahile și Ulise. Eschil, Sofocle și Euripide au pus bazele teatrului clasic cu operele Orestia, Oedip rege, Antigona și Medeea. Comedia s-a născut tot în Grecia. Aristofan a scris comediile satirice Viespile și Broaștele.",
