        "p": "Știința antică s-a dezvoltat pornind de la nevoi practice. Multe dintre descoperiri se folosesc și azi. Sumerienii foloseau sistemul sexagesimal (bazat pe numărul 60). Era comod, pentru că 60 se împarte exact la 2, 3 sau 4. Îl folosim și azi pentru timp și coordonate. Sumerienii au împărțit cercul în 360 de grade, ora în 60 de minute, minutul în 60 de secunde și anul în 360 de zile. În Antichitate oamenii știau să ridice numerele la pătrat și la cub, să calculeze rădăcina pătrată și să rezolve ecuații de gradul I și II. Geometria este considerată creația egiptenilor. Conceptul de zero a fost creat de indieni. Euclid a scris că lumina se propagă în linie dreaptă. Arhimede a calculat aria unei părți dintr-o parabolă și a inventat șurubul care îi poartă numele. Șurubul se folosește și azi pentru a pompa lichide, cărbune și cereale. El a explicat cum funcționează pârghia, dar nu a inventat-o. Pitagora spunea că numerele sunt esența lucrurilor. Teorema lui se folosește și azi în construcții, navigație și aviație. Mesopotamienii și babilonienii au făcut hărți ale cerului. Chinezii au făcut un calendar solar și au inventat busola, ceasul cu apă, mătasea, hârtia, cerneala, fonta, porțelanul și praful de pușcă. Romanii au fost arhitecți geniali. Munca lor științifică a constat mai ales în lucrări enciclopedice, cum este Istoria naturală a lui Pliniu cel Bătrân. Egiptenii cunoșteau anatomia. Papirusul Ebers conține 100 de rețete pentru bolile de ochi. Chinezii au dezvoltat acupunctura și medicamentele din plante. Iordanes scrie că Deceneu i-a învățat pe daci logica, mersul planetelor și zodiacul. Dioscoride a lăsat o listă cu 42 de plante medicinale, cu numele lor dacice. Herodot este considerat cel mai mare istoric al Antichității. Tucidide a fost primul care a dat importanță faptelor economice și sociale.",
