        "t": "3. Portret istoric. Solomon, unul dintre „cei șapte înțelepți” ai Antichității",
        "p": "Solomon a fost al zecelea fiu al regelui David, cel care l-a învins pe uriașul filistin Goliat. Spre deosebire de tatăl său, Solomon a avut o domnie liniștită și bogată, de 40 de ani (971–931 î.H.). A fost organizator, diplomat și constructor. A împărțit Israelul în 12 triburi, cu 12 districte administrative. Se spune că, după ce a ajuns rege, i-a cerut lui Dumnezeu înțelepciune. Dumnezeu i-a dat-o drept răsplată, pentru că nu a cerut bogății, viață lungă sau moartea dușmanilor. Lui Solomon i se atribuie cărțile Proverbe, Înțelepciunea lui Solomon, Ecleziastul și Cântarea Cântărilor. A avut legături diplomatice și de comerț cu fenicienii, arabii și egiptenii. A luat în stăpânire fortăreața Geser din Canaan, a construit un port și un șantier naval și a creat o întreprindere de comerț pe mare, condusă de stat. A asigurat siguranța caravanelor pe drumurile care treceau prin Palestina și lua taxe de tranzit. A adus fierari din Fenicia și constructori de corăbii din Tir. Regatul lui Solomon cumpăra din alte țări fildeș, pietre prețioase, lemn de cedru, abanos și santal, aur, argint și piei. Comerțul cu cai era controlat doar de el și a devenit legendar. Cu bogățiile sale a construit Marele Templu din Ierusalim. După Biblie, el a fost distrus de babilonieni. Al Doilea Templu a fost distrus de romani, în anul 70 d.H. O parte din zidul lui, Zidul Plângerii, este de două mii de ani cel mai sfânt loc al iudaismului. În vremea lui Solomon, Ierusalimul a devenit un oraș în care trăiau oameni din multe țări. Solomon este socotit unul dintre „cei șapte înțelepți” ai lumii antice.",
