        "t": "7. Patrimoniu istoric. Monumente de arhitectură antică și medievală din localitate/raion/regiune",
        "p": "Un proiect despre patrimoniu (monumentele locului unde trăiești) te ajută să fii curios, să gândești, să colaborezi cu alții și să fii responsabil. El are patru etape: proiectare, planificare, realizare și evaluare. Manualul dă ca exemplu fortificația geto-dacică de la Butuceni, din comuna Trebujeni, raionul Orhei. Este una dintre cele mai importante dave din zona dintre Prut și Nistru. Are formă ovală, alungită. Partea de nord este stâncoasă și se înalță cu 60 de metri deasupra râului Răut, cel mai mare afluent al Nistrului. Arheologii au arătat că pe vârful dealului au trăit oameni încă din secolele VIII–VII î.H., adică de circa 2.800 de ani. În secolul al V-lea î.H. geții au întărit așezarea cu ziduri și au refăcut de mai multe ori sistemul de apărare. El era format din șanțuri legate între ele prin valuri de pământ. Șanțurile erau adânci de 3,5 metri și late de 4,5–7 metri. Valurile, împreună cu stâlpii de lemn, ajungeau la 10–20 de metri. În citadelă se intra printr-o poartă din partea de est. În locul cel mai înalt s-au găsit urmele unei clădiri rotunde, pentru închinare, cu vatră de piatră și trei rânduri de stâlpi. Se crede că ea avea legătură cu calendarul. Cetatea a fost un centru militar și politic puternic al geților. A fost la apogeu în secolele IV–III î.H. Mărfurile grecești veneau pe apă și se împrăștiau de aici în cetățile de pe ambele maluri ale Răutului. Ceramica grecească era roșie. Iar în amfore se aduceau vinuri și uleiuri.",
