        "t": "1. Criza societății antice și formele ei de manifestare",
        "p": "Începând cu secolele III–V d.H., societatea antică a început să se destrame. Munca sclavilor nu mai aducea profit, oamenii se răsculau, iar popoarele migratoare atacau tot mai des Imperiul Roman. Criza a fost politică, economică, socială și militară. Din punct de vedere politic, în secolele III–IV puterea împăratului, administrația și armata au slăbit. În secolul al III-lea au fost mulți împărați slabi. Commodus a condus ca un tiran. Romulus Augustulus avea doar 13 ani când a fost făcut împărat. Senatul, ajuns la 900 de membri, făcea comploturi împotriva împăraților. Dioclețian (284–305) a introdus dominatul, adică puterea absolută a împăratului. A creat tetrarhia, conducerea a patru oameni: doi auguști și doi cezari. A grupat provinciile mici în 12 dioceze și a împărțit armata în două: cea de la graniță și cea care mergea în campanii. A despărțit funcțiile militare de cele civile. Armata a crescut până la 500.000 de soldați, printre care și barbari. A introdus și un impozit general, care putea fi plătit și în produse. Constantin cel Mare (306–337) a continuat reformele. În 313 a dat Edictul de la Milano. În 324 l-a învins pe Liciniu. În 330 a întemeiat Constantinopolul, „Noua Romă”, pe locul coloniei grecești Byzantion. Locul era bun din punct de vedere strategic, între două continente și două mări. Constantin i-a legat pe coloni de pământ, pe meșteșugari de meseria lor și pe orășeni de locul unde s-au născut. Asta a dus la apariția feudalismului. Societatea s-a împărțit în honestiores (nobili, cavaleri, orășeni bogați) și humiliores (oamenii de rând). Teodosiu I (379–395) a împărțit imperiul între fiii săi: Arcadius a primit răsăritul, cu capitala la Constantinopol, iar Honorius apusul. Criza economică a adus scăderea valorii banilor (dinarul), scumpirea și întoarcerea la schimbul de mărfuri (troc). Istoricul Ammianus Marcellinus descrie invaziile ca pe un semnal de război în toată lumea romană.",
