        "p": "Între secolele III și XI, în Europa a avut loc marea migrație a popoarelor. Unii migratori erau germanici (goți, vandali, angli, saxoni, longobarzi, suevi, frizi și franci). Alții veneau din stepele Asiei (huni, avari, bulgari și alani). Din Europa de Est au venit slavii. În ultimul val au venit arabii, vikingii, normanzii, ungurii, maurii, turcii și mongolii. Înainte de invazii, imperiul era slăbit. Avea probleme cu puterea împăratului, cu economia, cu numărul de oameni și cu armata. Nici împărțirea lui în două, făcută de Teodosiu I, nu a salvat situația. Barbarii au atacat mai ales Imperiul de Apus, care era mult mai slab decât cel de Răsărit, cu capitala la Constantinopol. Din cauza schimbărilor de climă, în primele secole ale erei noastre, un grup mare de triburi germanice a plecat din Scandinavia și a ajuns lângă râurile Vistula și Oder. Populația creștea și se trecea de la viața nomadă la cea așezată, așa că se lupta pentru pământ. Nobilii și conducătorii militari trăiau din războaie și jaf, iar bogățiile „Cetății Eterne” (Roma) îi atrăgeau. Invaziile au avut succes și pentru că în legiunile romane erau mulți barbari. Hunii erau numiți și Călăreții Apocalipsei. În 375 ei i-au învins pe ostrogoți și pe vizigoți. În 451, conduși de Attila, au fost învinși de romani și de vizigoții lui Teodoric I, pe Câmpiile Catalaunice. Alaric, conducătorul vizigoților, a asediat Roma de trei ori și a intrat în ea la 24 august 410, jefuind-o. Vizigoții s-au așezat apoi în Spania. Regatul lor a fost distrus de arabi în 711. Migrațiile au avut multe urmări. Imperiul de Apus s-a destrămat și au apărut regate barbare. Drumurile de comerț au devenit periculoase. Moneda a dispărut, iar oamenii au făcut schimb de mărfuri. Pământul a devenit principala bogăție. Au apărut două grupuri sociale: proprietarii de pământ și țăranii dependenți de ei.",
