        "t": "3. Studiu de caz. Căderea Imperiului Roman de Apus",
        "p": "Imperiul Roman a durat aproape 500 de ani. S-a născut pe vremea lui Octavian Augustus, a fost cel mai întins pe vremea lui Traian și s-a prăbușit în 476, pe vremea lui Romulus Augustulus, un împărat copil. Cauzele căderii au fost economice, politice, sociale, militare și ideologice. Peste ele s-au adăugat atacurile barbare. Dioclețian, Constantin cel Mare și Teodosiu I au încercat să salveze imperiul prin reforme, dar au reușit doar să amâne căderea. Începutul sfârșitului a fost împărțirea definitivă a imperiului de către Teodosiu I, în 395. Fiii și nepoții lui au depins de generalii lor germanici. Honorius a mutat capitala de la Roma la Ravenna, în 402. El a fost condus de generalul Flavius Stilicho, un vandal, care oprise înaintarea triburilor germanice în Italia. Valentinian al III-lea, ultimul împărat din dinastia lui Teodosiu, a fost influențat de mama sa și de generalul Flavius Aetius. Aetius l-a învins pe Attila la Chalons, în 451. Valentinian l-a omorât pe Aetius, iar apoi a fost el însuși ucis de susținătorii lui Aetius. Relațiile încordate cu Imperiul de Răsărit au înrăutățit situația. În 475, Romulus Augustulus a luat tronul la Ravenna. În 476 a fost înlăturat de Odoacru, un prinț germanic, fost mercenar. Odoacru a devenit primul conducător barbar al Italiei. A lăsat Senatul să funcționeze, i-a pus pe romani și pe germanii din Italia pe picior de egalitate și a oprit alte invazii germanice. În 493 a fost ucis de Teodoric, trimis de Imperiul de Răsărit. Imperiul de Răsărit a avut împărați ca Marcian, Leon I, Zenon și Iustinian I, iar Constantinopolul a devenit centrul lumii. Și a fost cucerit de turci la 29 mai 1453.",
