        "t": "4. Portret istoric. Constantin cel Mare",
        "p": "Constantin I cel Mare s-a născut la Naissus, în provincia Moesia Superior. Tatăl lui era generalul Constantius Chlorus, iar mama, Flavia Iulia Helena, este cunoscută azi ca Sfânta Elena. Când tatăl lui a murit, armata l-a proclamat împărat. El a acceptat să facă parte din tetrarhie. Curând a cucerit Spania (310), a intrat în Italia și l-a învins pe Maxențiu la Podul Milvius, în 312. Liciniu era împărat în provinciile din răsărit și, din 313, cumnatul lui Constantin. În 313 cei doi au dat Edictul de la Mediolanum, care declara creștinismul egal cu celelalte religii. În 324 Liciniu a fost învins, prins și executat. Constantin s-a considerat trimisul lui Dumnezeu și apărătorul creștinismului. A plătit Bisericii pentru bunurile luate și a dat bani pentru biserici noi. A anulat unele pedepse (mutilarea, sclavia temporară) și a dat legi noi pentru familie și căsătorie. În 325, la conciliul ecumenic de la Niceea, au fost puse bazele credinței creștine, adică Crezul. Constantin și mama sa, Elena, au fost canonizați (făcuți sfinți). În ortodoxie, el este „întocmai cu apostolii”. Constantin a continuat reformele lui Dioclețian. A grupat provinciile în dioceze și a creat moneda de aur numită solidus. A împărțit armata în trupe de graniță și trupe de campanie. A construit un pod peste Dunăre și a apărat teritoriul din Dacia reocupat de romani cu un zid de apărare (limes), numit azi Brazda lui Novac. La 11 mai 330 a fost inaugurat Constantinopolul, noua capitală. La început s-a numit Noua Romă. A devenit centrul lumii creștine și cel mai mare și mai bogat oraș al Europei.",
