        "t": "5. Contribuția civilizației antice la făurirea tezaurului civilizației universale",
        "p": "Antichitatea ne-a lăsat o moștenire uriașă. În politică, statul a apărut în mileniul IV î.H., cu formele lui: orașe-state, regate și imperii. Primele orașe-state au apărut în Mesopotamia (Ur, Nippur, Lagaș, Uruk). În Grecia a apărut polisul, care s-a răspândit prin marea colonizare în jurul Mării Mediterane și al Mării Negre. La Roma, în 509 î.H., s-a născut republica (res publica). Grecii au dat civismul și democrația, „puterea poporului”. Adunarea Poporului (Ecclesia) și Senatul roman sunt organe de conducere care se păstrează și azi. În Orient s-a născut despotismul, adică puterea nelimitată a unui singur om. Scrisul a însemnat trecerea la civilizație. Scrierea cuneiformă a apărut în Sumer. Cea hieroglifică s-a dezvoltat în Egipt și China. Fenicienii au inventat alfabetul, pe care l-au luat grecii și romanii. Alfabetul latin se folosește și azi. În anul 105 d.H., Cai Lin, un eunuc de la curtea chineză, a inventat hârtia. Ea a ajuns în Europa prin Arabia abia în secolul al XIII-lea. Cuvântul liceu vine de la Aristotel, iar academie de la Platon. Folosim azi cuvinte moștenite din Antichitate: bibliotecă, Constituție, istorie, geografie, matematică, teatru, filozofie. În economie, oamenii au îmbunătățit uneltele și au inventat irigațiile, roata și calendarul. Comerțul s-a dezvoltat și, în secolul al VII-lea î.H., au apărut monedele. Drahma grecească și denarul roman au circulat în toată Europa. Drumul regilor, Drumul Mătăsii și drumurile romane ajutau la schimbul de mărfuri. În 776 î.H. au început Jocurile Olimpice, la Olimpia, o dată la patru ani. În cele cinci zile de întreceri, războaiele se opreau. Teodosiu I le-a interzis în 393, pentru că le credea păgâne. Au fost reluate abia în 1896. Din Antichitate am moștenit și teatrul, comedia și tragedia grecească, pe care romanii le-au adaptat (Colosseum), arhitectura și cele șapte minuni ale lumii.",
