        "t": "1. Geneza societății medievale",
        "p": "„Evul Mediu” este un nume dat de italieni, în timpul Renașterii, perioada dintre Antichitatea târzie și epoca modernă. În secolul al XV-lea, istoricul italian Flavio Biondo a folosit termenul în cartea Istoria de la căderea Romei, pentru anii 500–1500, până la cucerirea Constantinopolului (1453). Alți istorici iau ca reper descoperirea Americii (1492) sau revoluțiile din Țările de Jos (1566–1609) și din Anglia (1642–1649). În secolul al XVIII-lea, termenul a ajuns să însemne „Ev Mediu întunecat”. Oamenii se gândeau la cruzimile Inchiziției, la arderea pe rug a vrăjitoarelor și a ereticilor și la lipsa de cultură. În secolul al XIX-lea, în epoca romantismului, Evul Mediu a fost privit mai bine și idealizat în literatură și artă. Societatea medievală se baza pe feudalism. În acest sistem, pământul și țăranii erau stăpâniți de aristocrația care deținea terenuri agricole și făcea războaie. Feudalismul s-a dezvoltat complet în Franța, în secolele IX–XIV. Feudalii aveau puterea economică și politică. Țăranii și-au pierdut tot mai mult libertatea și au ajuns șerbi (dependenți de stăpân). Societatea medievală a apărut la întâlnirea a două lumi: lumea antică greco-romană și lumea barbară. Miron Costin scrie că adevăratul nume al românilor este „rumân”, adică roman. El s-a păstrat de la primul descălecat al lui Traian.",
