        "p": "La sfârșitul secolului al IV-lea, triburile germanice au pornit tot mai multe spre vestul imperiului. Ele au grăbit căderea Imperiului Roman de Apus, în 476. În secolul al V-lea, vestul Europei era locuit numai de triburi germanice. Majoritatea regatelor purtau numele migratorilor: regatul vizigoților, al vandalilor, al francilor, al anglo-saxonilor. Unele au durat puțin. Altele, ca cele anglo-saxone, au durat mai mult. În secolul al V-lea începe istoria Galiei, legată de Clovis (481–511). Era fiul lui Childeric, un conducător franc și general roman. Clovis făcea parte din dinastia merovingiană. Numele ei vine de la Merovech, care a fost mai degrabă un erou de legendă decât o persoană reală. Clovis a fost primul rege germanic care a devenit creștin. Așa și-a atras sprijinul Bisericii. Regatul lui rămânea barbar. Regele avea putere absolută și era conducătorul armatei. La moartea sa, în 511, regatul a fost împărțit între cei patru fii, după obiceiul germanic. Ostrogoții conduși de Teodoric au cucerit Italia în 489. Odoacru a fost ucis în 493 și s-a format regatul ostrogot. Teodoric a unit tradițiile romane cu cele barbare. A respectat cultura romană clasică și a avut ca sfătuitori pe Boethius și Casiodor. Bulgarii, un popor din Asia, au trecut Dunărea sub conducerea lui Asparuh și au creat un stat. Bizantinii l-au distrus în 1018, iar în 1185 el a apărut din nou, ca Țaratul vlaho-bulgar.",
