        "t": "5. Fărâmițarea feudală. Centralizarea statelor medievale",
        "p": "Regatele barbare formate în secolele V–VII au păstrat unele obiceiuri romane, amestecate cu cele germanice, și după căderea imperiului în 476. Francii au trecut de la regat la imperiul carolingian. El se considera urmașul Imperiului Roman. În 800 Carol cel Mare s-a încoronat la Roma, dar statul lui nu a rezistat mult. Statul medieval din Occident a evoluat de la primele „state feudale” (secolele V–VI) până la absolutismul regelui (secolele XVI–XVII). Momentul hotărâtor a fost în jurul anului 1000. Atunci, după ce statul carolingian se fărâmițase, regii au început să refacă statul. Statul carolingian era împărțit în comitate, conduse de comiți (viitorii conți). Ei administrau, judecau, conduceau armata și strângeau impozite. Biserica lucra împreună cu regele. După moartea lui Carol cel Mare, imperiul a intrat în criză. Cauzele au fost: populațiile din imperiu erau la nivel diferit de dezvoltare, nu exista unitate economică, feudalii deveneau tot mai puternici, statul se împărțea între urmași, iar din afară veneau pericole. Prin Tratatul de la Verdun, din august 843, trei regi s-au întâlnit și au împărțit regatul. Ludovic a primit partea de răsărit, Carol pe cea de apus, iar Lothar, cel mai mare dintre ei, partea din mijloc. Au apărut regate fărâmițate, în care oamenii erau legați prin vasalitate (promisiunea de credință față de un senior). S-a trecut la monarhia feudală. Pe la anul 900, puterea era foarte împrăștiată în tot Occidentul, pe baza vasalității. Hugo Capet a fost primul rege al dinastiei Capețienilor. Iar regele era stăpânul marilor seniori și nu putea fi vasalul nimănui.",
