        "t": "6. Portret istoric. Carol cel Mare",
        "p": "Numele lui Carol cel Mare este foarte important pentru istoria Europei. A devenit rege al francilor în 768, la 24 de ani. A întărit statul, a ocupat nord-estul Spaniei, nordul Italiei, Saxonia, Bavaria și o parte din hanatul avarilor. În 778 a pornit spre Spania, dar a trebuit să se retragă de la zidurile orașului Zaragoza, pentru că saxonii s-au răsculat. La întoarcere, ariergarda (partea din urmă a armatei), lăsată în grija lui Roland, prefectul mărcii Bretagne, a fost atacată și nimicită de basci în trecătoarea Roncevaux. Roland nu a vrut să sune din corn după ajutor, pentru că socotea asta o lașitate. A murit ca un erou. Întâmplarea este povestită în poemul Cântecul lui Roland, din secolul al XI-lea. La 25 decembrie 800, Carol s-a încoronat la Roma ca împărat roman. Eginhard îl descrie ca pe un om lat în umeri și voinic, înalt, cu ochi mari și vioi, păr alb și față veselă. Îi plăceau vânătoarea și înotul. Nu îi plăceau hainele luxoase. Știa latina și îi respecta pe oamenii învățați. La încoronare a promis că va aduce pacea Bisericii, că va înlătura nedreptatea și că va lupta împotriva dușmanilor lui Dumnezeu. Din secolul al XII-lea, promisiunea a devenit un jurământ. Regele era uns pe frunte cu mir și devenea „alesul lui Dumnezeu”. Carol este numit și părintele Europei. El i-a obligat pe funcționarii de la curte să învețe carte. Epoca lui se numește renașterea carolingiană. Atunci au fost redescoperite artele liberale (materiile de bază ale școlilor medievale), care au fost introduse în școlile din Occident, și a fost reluată gândirea lui Aristotel.",
