        "t": "10. Formațiuni prestatale românești. Formarea Transilvaniei. Constituirea Țării Românești",
        "p": "În secolele VIII–IX, popoarele migratoare nu mai atacau atât de des. Atunci au apărut formațiuni politice de dinainte de stat: voievodate, țări, banate și jupânate. Ele semănau cu ducatele din Occident. În 896, când ungurii s-au așezat în Panonia, în Transilvania existau trei voievodate. Ele sunt descrise de un cronicar anonim în Gesta Hungarorum. Voievodatul lui Menumorut era în Crișana, între Tisa, Someș și Mureș, cu reședința în cetatea Bihor. Voievodatul lui Glad era în Banat, între Dunăre și Mureș, cu reședința la Cuvin. Voievodatul lui Gelu era în Transilvania, cu reședința la Dăbâca, lângă Cluj. Ele aveau vechi tradiții de conducere și o armată puternică, cu cavalerie, arcași și cetăți. De aceea ungurii, deși au câștigat bătălii, nu au putut alipi voievodatele la Ungaria. Viața Sfântului Gerard, din secolul al XII-lea, arată că, după mai bine de un secol, existau două ducate. Primul era al lui Ahtum, din Morisena, peste teritoriul lui Glad și o parte din cel al lui Menumorut. Al doilea era al lui Gyula, peste teritoriul lui Gelu Românul. Asta arată că spațiul românesc se unifica. Ahtum a fost botezat la Vidin, după legea grecilor. El avea oști mai numeroase decât ale regelui. Alte formațiuni apar în Diploma Ioaniților. Prin ea, regele Ungariei le dă ospitalierilor țara Severinului și cnezatele lui Ioan și Farcaș, până la Olt. Din anul 1000, în vremea regelui Ștefan I, Transilvania a intrat treptat în statul maghiar. La sud de Carpați, Basarab I a fost domn al Țării Românești. În 1330, la Posada, l-a învins pe regele Carol Robert de Anjou și astfel Țara Românească a devenit independentă.",
