        "t": "11. Constituirea Țării Moldovei",
        "p": "În secolul al XIII-lea, genovezii au făcut din orașele de pe malul Mării Negre centre ale comerțului european. Drumurile spre Chilia, Cetatea Albă și Caffa treceau prin zona de la est de Carpați, stăpânită de Hoarda de Aur. Ungaria și Polonia voiau să scape de această putere. În valea Moldovei exista un voievodat cu reședința la Baia, condus de voievodul maramureșean Dragoș, vasal al regelui Ungariei. Legenda spune că Dragoș a venit din Maramureș, vânând un bour. A găsit pământuri bune, fără locuitori. A adus oameni din Maramureș și a întemeiat statul. Capul de bour a ajuns în stema Moldovei. Grigore Ureche povestește că păstorii din Maramureș au urmărit un bour până la un râu. L-au ucis la Boureni și au întemeiat un sat. După Dragoș au urmat fiul său Sas și nepotul Balc. În Maramureș, voievodul Bogdan stăpânea nouă sate și avea reședința la Cuhea, pe valea Izei. El s-a împotrivit regilor unguri Carol Robert și Ludovic I, care voiau să desființeze autonomia locală. În 1343 a fost declarat „infidel”, iar în 1349 „necredincios”. În 1359 Bogdan a trecut munții. Prin acțiunea lui și a războinicilor lui a fost înlăturată stăpânirea regelui ungur, iar în 1359 Moldova a devenit stat independent. Bogdan a pus bazele unei dinastii domnitoare.",
