        "t": "12. Sinteze analitice. Similitudini și particularități în procesul genezei statale la români",
        "p": "După câteva secole, societatea românească avea destui oameni, destulă bogăție și destulă putere spirituală pentru o nouă etapă. Nicolae Iorga a numit-o „de la sat la stat”. Statele medievale românești s-au format în secolele XIII–XIV. Cauzele au fost interne, cum ar fi creșterea numărului de sate. Contextul extern a ajutat, iar presiunea regelui Ungariei a scăzut după o criză a dinastiei. Hoarda de Aur a intrat și ea într-o criză militară. Formarea Țării Românești, a Moldovei și a Transilvaniei a avut asemănări și deosebiri. O asemănare este descălecatul. În Țara Românească el se bazează doar pe tradiție, iar în Moldova este confirmat și de izvoare. Țara Românească și Moldova au început ca vasale ale regelui Ungariei, apoi au devenit independente: prima în 1330, a doua în 1359. Formarea statelor a fost un proces complex și unitar. A cuprins toate regiunile de la est, de la sud și din interiorul Carpaților. Izvoarele menționează circa 25 de țări și voievodate și mai multe cnezate. Asta arată unitatea românilor. Pericolul din afară venea de la tătari și de la unguri. Când ei au ajuns la curbura Carpaților, existau deja state cu dinastii domnitoare proprii. Țara Românească era orientată spre Ungaria, iar Moldova spre Polonia și Lituania. Transilvania a fost stăpânită devreme de regii unguri. De aceea nu a intrat în unificarea politică a românilor.",
