        "t": "13. Studiu de caz. Geneza statală: între legendă și adevăr istoric",
        "p": "Statele românești de la est și de la sud de Carpați s-au format aproape în același timp. Izvoarele din Evul Mediu vorbesc despre asta foarte pe scurt. Pentru că lipseau documentele, mult timp s-a crezut ce spuneau cronicile despre „descălecat” (întemeierea statelor). Legendele vorbesc despre un dublu descălecat în Moldova: întâi al lui Dragoș, apoi al lui Bogdan. Cronica lui Ioan de Târnave spune că Bogdan, voievodul românilor din Maramureș, i-ar fi trecut pe români la est de Carpați, pe ascuns. Acolo era un teritoriu care aparținea Ungariei, dar era puțin locuit din cauza tătarilor. Mai târziu au fost tot mai mulți români și a apărut Țara Moldovei. Legenda lui Dragoș, venit din Maramureș vânând un bour, folosește ca argument stema Moldovei, cu cap de bour. Dar această versiune nu are temei în realitatea istorică. În Țara Românească, cronicile spun că Radu Negru, voievod în Ardeal și herțeg al Amlașului și Făgărașului, a coborât la Câmpulung, pe apa Dâmboviței. Acolo și-a făcut curți și mănăstiri. Basarab, banul Craiovei, i s-a supus, iar apoi Radu Negru a mutat scaunul la Curtea de Argeș. Teoria continuității spune că aceste pământuri au fost mereu locuite. Întărirea statelor s-a făcut asemănător în toate teritoriile românești și a dus la unificare și la libertate politică. Bogdan I este cel care a desăvârșit întărirea statului Moldova.",
