        "t": "1. Viața economică în societatea medievală. Apariția și dezvoltarea orașelor medievale",
        "p": "În Evul Mediu, cei mai mulți oameni trăiau la sat. Ei lucrau pământul sau creșteau animale. Recoltele depindeau de vreme: de temperatură și de ploi. Când recoltele erau slabe, venea foametea. Între 300 î.H. și 400 d.H. clima s-a răcit. Între 750 și 1215 a devenit mai caldă și mai uscată. Domeniul feudal avea două părți. Prima era rezerva seniorului: castelul, morile, teascul, cuptorul, ogoarele, viile, pădurile și iazurile. A doua erau loturile date țăranilor dependenți. Ei plăteau rentă seniorului (muncă, produse sau bani) și zeciuială Bisericii. În Evul Mediu timpuriu (secolele V–X) uneltele erau simple. Plugul avea brăzdar de lemn, nu avea roți și era tras de boi. Sapa era de lemn. Se cunoștea doar asolamentul bienal: pământul se împărțea în două, iar o jumătate se lăsa să se odihnească un an. Îngrășămintele naturale se foloseau doar în grădini. Din secolul al XI-lea (în unele locuri din secolul al IX-lea) a avut loc revoluția agrară. A apărut asolamentul trienal, pe trei părți, și două recolte în perioade diferite ale anului. Plugul a primit brăzdar de fier, roți și cormană, astfel ara mai adânc. S-a folosit și grapa. Calul a început să tragă la plug, cu un colier rigid care nu-l sufoca, din secolul al IX-lea. Potcovitul l-a făcut mai puternic. Suprafețele cultivate s-au mărit prin tăierea pădurilor, uscarea mlaștinilor, arătura pământului necultivat și îndiguirea terenurilor. A crescut producția și numărul de oameni. Ca să aducă muncitori, marii proprietari le promiteau coloniștilor libertate, un lot de pământ și obligații mai mici. Recoltele mai bune au dus la mai multe oi, porci și vite. Meșteșugarii (olari, țesători, zidari, dulgheri, măcelari, brutari, croitori) au început să folosească metode noi.",
