        "t": "2. Tablou istoric. Orașul Lvov",
        "p": "Lvov (Lviv, Leopolis, „orașul leului”) este cel mai mare și mai important oraș din regiunea istorică Galiția, azi în Ucraina. A fost întemeiat în 1256. S-a dezvoltat repede, pentru că se afla la încrucișarea drumurilor de comerț care legau Marea Neagră de Marea Baltică. Negustorii din Lvov foloseau dreptul de depozit. Comercianții care treceau prin oraș trebuiau să stea 14 zile și să-și arate marfa negustorilor locali. Aceștia o cumpărau ieftin și o vindeau mai scump. Conducătorii și-au dat seama cât sunt de importanți negustorii și le-au dat privilegii. Primul a fost regele Poloniei, apoi alte state vecine, printre care Moldova și Țara Românească. În privilegiul dat de Alexandru cel Bun lvovenilor sunt amintite mătasea, piperul, camha (o stofă de mătase din Orient), tămâia, vinul grecesc, scorțișoara, smochinele uscate, caii scumpi, postavurile din Bruges și Florența și cupele. Măcelarii din Lvov cumpărau vite din Moldova. În privilegiul din 1403, Mircea cel Bătrân le-a dat voie negustorilor din Lvov să vină cu mărfurile la Târgoviște, unde plăteau vamă. Apoi puteau circula prin toată țara, până la Brăila. După ce otomanii au cucerit Chilia și Cetatea Albă, în 1484, comerțul cu Lvovul a avut mult de suferit. Nicolae Iorga scrie că în Lvov trăiau ruși, armeni, evrei, tătari și alte neamuri, fiecare după legea lui. Azi centrul istoric al orașului, cu clădiri medievale și din perioada Imperiului Habsburgic, este pe lista UNESCO. Circa 55% dintre monumentele de patrimoniu ale Ucrainei sunt în Lvov.",
