        "t": "3. Economia Țărilor Române (sf. sec. XIV – mijl. sec. XVII)",
        "p": "În Europa Centrală și de Sud-Est au venit invazii mongole și epidemii de ciumă. De aceea, în Evul Mediu predomina o economie închisă, cu puțin comerț. În spațiul românesc, înființarea Țărilor Române a creat condiții pentru progres economic. Au contribuit creșterea populației și noile sate din secolul al XIV-lea. Țările Române se aflau la întâlnirea mai multor drumuri de comerț. Drumul tătăresc și drumul moldovenesc legau Cetatea Albă și Chilia, prin Moldova, de Lvov, Germania și Cracovia. Iar alte drumuri urmau Dunărea. Câștigurile din comerț au dus la creșterea orașelor și au ajutat domnia să se întărească. La 20 ianuarie 1368, Vladislav Vlaicu le-a dat brașovenilor un privilegiu pentru comerț. Mircea cel Bătrân l-a reînnoit în 1413, iar urmașii lui l-au reînnoit de șapte ori, până în 1444. În Moldova, Alexandru cel Bun și Ștefan cel Mare au dat nouă acte de acest fel negustorilor din Sibiu și Brașov. Dintre cele două ocupații de bază, agricultura era foarte importantă. Se tăiau pădurile și se ara pământ nou. Se spune că la plug se înjugau uneori și 12 boi. S-au răspândit grapa cu dinți de lemn, brăzdarul de fier și munca cu animale. Morile de apă și de vânt erau în sate și orașe. Se cultivau grâu, mei, orz, secară, ovăz, cânepă, in, ceapă, usturoi, napi, mazăre și varză. Iar cerealele se păstrau în gropi arse. Domnii construiau hambare, pentru că dările erau mai ales în cereale. Pământul era principala bogăție a Evului Mediu. Animalele erau principala marfă de export.",
