        "t": "6. Instituțiile în statul medieval occidental",
        "p": "Statul medieval era o formă de organizare politică, cu instituții și legi proprii, care avea puterea asupra unui teritoriu. Instituțiile lui principale erau monarhia, sfatul monarhului, adunările reprezentative, justiția, armata și Biserica. Ele veneau din Imperiul Bizantin și din cel Carolingian. După căderea Romei, instituțiile romane s-au amestecat cu cele germanice. Regele nu a mai fost doar un șef de armată, ci conducătorul unui stat. În secolul al VII-lea, odată cu creștinismul, a apărut monarhia de drept divin. Regele era reprezentantul lui Dumnezeu pe pământ. Pepin cel Scurt (751–768), regele francilor, a fost primul monarh occidental considerat sacru. Centrul statului carolingian era palatul, unde locuiau familia regelui și nobilii. Până în secolul al XI-lea, puterea regelui era mai ales simbolică, din cauza vasalității („vasalul vasalului meu nu-mi este vasal”). Marii vasali trebuiau să vină la curtea regelui pentru sfat și ajutor. În secolul al XI-lea regii au început să cheme adunări de reprezentanți, ca să discute probleme politice, de bani, de justiție sau de război. Aceasta era monarhia stărilor. Adunările se numeau: Stările Generale în Franța, Cortesurile în Spania, Reichstagul în statele germane, Parlamentul în Anglia, Sejmul în Polonia, Dieta în Ungaria și Adunarea Țării în Moldova și Țara Românească. În secolele XIV–XV s-a născut monarhia absolută. Magna Charta Libertatum din 1215 spunea că niciun om liber nu poate fi închis sau lipsit de avere decât prin judecata egalilor săi sau după legea țării și că dreptatea nu se vinde.",
