        "t": "9. Sinteze analitice. Războaiele și caracterul lor în Evul Mediu. Războiul de 100 de Ani",
        "p": "Războiul este un lucru rău, dar a existat în toate epocile. Războaiele din Evul Mediu au adus tactici și arme noi. Ele puteau fi interne sau externe. Cele interne erau între seniori și vasali care nu își respectau obligațiile, între vecini pentru teritorii sau purtate de regi, ca să-i aducă la ascultare pe vasalii rebeli. Cauzele erau politice, economice sau religioase. Concurența în comerț a dus la lupte între orașele italiene Veneția, Florența și Milano. În Franța, între 1562 și 1598, a avut loc războiul dintre catolici și calvini (hughenoți). Războiul celor Două Roze (1455–1485) a fost între casele York (trandafir alb) și Lancaster (trandafir roșu) din Anglia. S-a încheiat când Henric al VII-lea Tudor l-a învins pe Richard al III-lea la Bosworth Field. Cele două dinastii s-au unit printr-o căsătorie. Războaiele externe se purtau pentru cucerirea de teritorii, certuri între dinastii, resurse sau drumuri de comerț. Cele mai multe erau războaie de cucerire, ca ale Imperiului Otoman. Până în 1400, armatele erau formate din țărani. Apoi au apărut armate de profesioniști, mercenarii. Cavalerii aveau mare importanță. Războiul de 100 de Ani (1337–1453) a fost între regii Angliei și ai Franței. A început în 1337, când englezii au distrus flota franceză. La Crécy, în 1346, arcașii și sulițașii englezi au măcelărit cavaleria franceză. La Poitiers, în 1356, regele Franței a fost luat prizonier. Au izbucnit o revoltă la Paris și răscoala țăranilor numită Jacqueria. În 1415, la Azincourt, englezii au câștigat din nou. În 1429 a fost asediat Orléans, iar tânăra Jeanne d'Arc a trezit din nou curajul francezilor.",
