        "t": "10. Expansiunea arabă. Cruciadele",
        "p": "Mahomed a întemeiat islamul și a fost profetul lui Allah. În anul 622 a fugit din Mecca la Medina, pentru că noua religie, cu un singur zeu, nu era pe placul negustorilor bogați din Mecca. În 630 a cucerit Mecca. Expansiunea arabă s-a făcut în numele religiei, care cerea războiul sfânt (jihad). După moartea profetului, conducerea a trecut la califi. Pe vremea califului Omar (634–644), arabii au cucerit Siria, Egiptul, Palestina, Irakul și Persia și au ajuns la zidurile Constantinopolului. Au cucerit nordul Africii și o parte din India. În 711 au ajuns în Spania, dar francii lui Carol Martel i-au oprit la Poitiers, în 732. Araba a devenit limba oficială a Califatului. Arabii au construit peste 200 de orașe cu moschei, palate, fântâni și băi publice. Au contribuit la știință, la literatură (O mie și una de nopți), la geografie, la filozofie și la astronomie. Algebra și cifrele arabe au ajuns în Europa. Medicii arabi foloseau anestezia și au deschis primele farmacii și spitale. Cruciadele au fost expediții ale creștinătății latine în Orient, mai ales în „Țara Sfântă”. Ele erau făcute de mai multe țări și aveau o mare pasiune religioasă. Numele vine de la crucea purtată de luptători. Schisma din 1054 și pierderea controlului asupra drumurilor de comerț l-au făcut pe papă să se hotărască. La Conciliul de la Clermont (1095), papa Urban al II-lea a chemat la eliberarea Ierusalimului. Prima cruciadă a avut două expediții: a săracilor și a cavalerilor. În 1099 cruciații au cucerit Ierusalimul. A doua cruciadă (1147–1149) a venit după pierderea orașului Edessa, Saladin a cucerit Ierusalimul. La a treia cruciadă au participat Richard Inimă de Leu, Frederic Barbarossa și Filip al II-lea al Franței. Prin Tratatul de la Jaffa, din 1192, Ierusalimul a rămas musulman, dar pelerinii creștini puteau să-l viziteze. În cruciada a IV-a (1202–1204), cruciații conduși de dogele Enrico Dandolo au cucerit Zara, apoi Constantinopolul, pe care l-au jefuit în 1204.",
