        "t": "8. Unirea politică a Țărilor Române",
        "p": "În 1599, noul principe al Transilvaniei, Andrei Báthory, și domnul Moldovei, Ieremia Movilă, voiau să colaboreze cu Poarta. Împreună cu hatmanul polon Jan Zamoyski, voiau să-l înlocuiască pe Mihai Viteazul cu Simion Movilă. Mihai a trimis o solie la Praga, în iulie 1599. A cerut împăratului Rudolf al II-lea voie să intervină în Transilvania. În octombrie 1599, trupele lui au trecut prin Buzău și pe valea Oltului în Transilvania. Au câștigat bătălia de la Șelimbăr (18/28 octombrie) împotriva lui Andrei Báthory. La 1 noiembrie 1599, Mihai a intrat victorios în Alba Iulia și a s-a proclamat principe al Transilvaniei. A îmbunătățit situația țăranilor români și a Bisericii Ortodoxe. A întărit din nou privilegiile secuilor și ale micii nobilimi românești. A dat acte în limba română, pe lângă cele în latină și maghiară. În martie 1600 a intrat în Moldova pe trei direcții. Ieremia s-a retras la Hotin, iar până la sfârșitul lui mai toată Moldova era a lui. Într-un document din 6 iulie 1600, el se intitula domn al Țării Românești, Ardealului și Țării Moldovei. Era prima mare unire politică a Țărilor Române. Ca s-o întărească, a dat înlesniri preoților și iobagilor români, a construit o biserică ortodoxă la Alba Iulia și a folosit aceeași stemă. Vecinii nu aveau încredere. Habsburgii voiau Transilvania în sfera lor, Polonia voia Moldova, iar Otomanii nu voiau să piardă Țările Române. Nobilii maghiari erau nemulțumiți de impozite și de rolul românilor și s-au răsculat, cu sprijinul generalului Basta. La 18 septembrie 1600, la Mirăslău, Mihai a fost învins. Așa a pierdut Ardealul. În Moldova, oastea lui Zamoyski l-a adus din nou pe Ieremia Movilă. Polonezii l-au învins pe Mihai la Bucov și la Curtea de Argeș și l-au pus domn pe Simion Movilă. Mihai a mers la Praga după ajutor. S-a întors și a câștigat la Guruslău, la 3 august 1601. Generalul Basta a dat ordin să fie ucis. Mihai a fost omorât la 9 august 1601, în câmpia de lângă Turda. Iar capul său a fost înmormântat la Mănăstirea Dealu.",
