        "t": "9. Situația politică a Țărilor Române în primele decenii ale secolului al XVII-lea",
        "p": "La începutul secolului al XVII-lea, soarta Țărilor Române depindea de marile imperii și de luptele lor pentru întâietate. Liga Creștină a continuat lupta împotriva otomanilor. Imperiul Otoman a ajuns la cea mai mare întindere, chiar dacă fusese învins în unele lupte. Imperiul Romano-German, condus de Habsburgi, lupta pentru întâietate. Polonia a pierdut întrecerea pentru dominarea sud-estului Europei, pentru că se ridica Imperiul Rus. După moartea lui Mihai Viteazul, Țările Române au intrat din nou în jocul marilor puteri. Ele voiau să-și pună oamenii pe tron. Domnii erau adesea numiți direct dintre grecii din Istanbul. Grecii bogați au primit titluri de boieri și moșii. Boierii de aici erau nemulțumiți. A început să se ceară plata în avans a tributului, iar tributul a crescut. Cel al Transilvaniei a urcat de la 15.000 la 40.000 de galbeni în 1658. Cel al Țării Românești era de 40.000 de galbeni (92.000 în vremea lui Constantin Brâncoveanu). Moldova plătea între 35.000 și 40.000. Radu Șerban, sprijinit de boierii Buzești, a domnit în Țara Românească între 1602 și 1611. A făcut campanii împotriva turcilor și în 1604 a fost recunoscut de Poartă. În 1610–1611, principele Gabriel Báthory a atacat Țara Românească. Poarta a răspuns punând domn pe Radu Mihnea, care prefera diplomația, iar în Moldova pe Ștefan Tomșa al II-lea. Așa s-a întărit din nou stăpânirea otomană. Gabriel Bethlen a primit de la sultan, în 1614, un ahidname (act de recunoaștere). Boierii greci au pus mâna pe comerț. Mănăstirile au început să fie închinate Muntelui Athos și Palestinei, așa că au plecat din țară bunuri de mare preț. Prin pacea de la Hotin (1621), Hotinul a fost dat înapoi Moldovei, dar Poarta a primit întâietatea asupra ei. Stabilitate în politică, în economie și în cultură au adus Matei Basarab (1632–1654) în Țara Românească și Vasile Lupu (1634–1653) în Moldova. Perioada lor se numește „între medieval și modern”.",
