        "t": "2. Patrimoniu istoric. Universitățile medievale",
        "p": "Universitatea s-a născut în Occident, în Italia, Franța și Anglia, la începutul secolului al XII-lea. Universitatea medievală se numea studium generale. Ea este modelul universității de azi. A apărut prima dată în 1088, la Bologna. Din 1229 documentele o numesc „Universitate”. Programa avea artele liberale: gramatica, retorica, logica, aritmetica, muzica, astronomia și geometria. În al doilea ciclu se putea urma una dintre facultățile superioare: teologia, medicina sau dreptul. Tinerii cu vârste cuprinse între 15 și 16 ani puteau susține, după doi ani de studii, examenul de bacalaureat pentru obținerea acestui titlu. Această tradiție s-a păstrat până azi. Universitatea nu era o școală, ci o formă prin care studenții și profesorii se organizau împreună. Unele universități, ca Padova și Cambridge, au apărut când profesorii și elevii au plecat dintr-un oraș în altul. Altele, ca Napoli și Salamanca, au apărut prin hotărârea unei autorități bisericești sau laice. O universitate trebuia să aibă cel puțin două facultăți. În 1170, Universitatea din Paris avea trei: Teologie, Drept și Medicină. La Teologie erau cei mai mulți studenți și profesori. Cursurile durau până la vârsta de 35 de ani, iar clericii aveau privilegii. La Oxford (1167) se întâlneau studenți și profesori din multe țări și se studia în latină. Toate universitățile din secolul al XIII-lea erau internaționale. În secolul al XIII-lea, profesorii s-au unit într-un grup profesional, collegium. S-au legat prin jurământ să-și apere împreună interesele, iar studenții li s-au alăturat. În secolul al XIV-lea au apărut multe universități noi, în Polonia, Suedia, Norvegia și Scoția. În spațiul românesc au apărut mai târziu. Iar azi ele fac parte din patrimoniul universal.",
