        "t": "7. Proiect de salvgardare a patrimoniului cultural",
        "p": "Cultura românească s-a format în mii de ani. Creatorii ei sunt oamenii din popor, autori necunoscuți ai poeziei populare, ai baladelor, basmelor și legendelor. Dintre balade, cea mai cunoscută este Miorița, o capodoperă a literaturii române. Unele tradiții populare sunt amenințate de viața modernă. Fetele își îmbină la sărbători straiele populare cu pantofi moderni. Colindele se aud tot mai rar, iar tinerii nu ascultă folclorul adevărat. Totuși, tradiția rezistă, iar străinii sunt impresionați de cât de autentice sunt obiceiurile noastre. Proiectul de păstrare a patrimoniului cultural se desfășoară în februarie–aprilie. Scopul lui este o revistă de istorie, tipărită sau online, numită Tezaur. Ea are texte, înregistrări audio, fotografii și filmări. Revista are mai multe rubrici. În Trandafir de la Moldova se pun 3–5 cântece adunate de la oameni în vârstă. În Intră-n casă, neamule sunt interviuri cu cinci persoane despre hramul satului. Un colaj cu fotografii vorbește despre obiceiurile de nuntă, cu informații și din Descrierea Moldovei a lui Dimitrie Cantemir. O rubrică este despre dansul popular (Alunelul, Arcanul, Bătuta, Brâul, Hora, Polca, Roata, Sârba). Alta este despre măștile de iarnă (Ursul, Cerbul, Căluțul, Capra, Berbecul, Vulpea). Ultima este despre costumul popular, care arată identitatea unui popor.",
