        "t": "2. Marile descoperiri geografice",
        "p": "Europenii cunoșteau doar trei continente: Asia, Africa și Europa. Despre drumurile spre India și China aflaseră din călătoria lui Marco Polo, din secolul al XIII-lea. Pe vechiul Drum al Mătăsii, mărfuri precum mirodeniile, citricele și mătăsurile erau aduse din Asia prin intermediul negustorilor arabi. Turcii au ocupat centrele de comerț și porturile din Marea Mediterană. Astfel au blocat drumurile comerciale. De aceea, europenii au căutat un drum pe mare spre India. Economia creștea și era nevoie de piețe noi. În 1440 a fost creată caravela, o corabie ușor de condus, iar hărțile au fost îmbunătățite. Expedițiile se făceau și la îndemnul Bisericii, pentru că botezarea localnicilor era o misiune importantă. Primele au pornit Spania și Portugalia, care voiau să domine comerțul pe mare. Portughezii au ajuns la Capul Verde. În 1487–1488 Bartolomeo Diaz a ajuns în capătul de sud al Africii, la Capul Bunei Speranțe. În timp ce Cristofor Columb (1451–1506) a navigat spre vest în căutarea unei noi rute către India, portughezul Vasco da Gama a reușit să ajungă la destinație în perioada 1497–1498, ocolind continentul african. Avea trei caravele: „Pinta”, „Santa Maria” și „Niña”. A plecat din portul Palos, în august 1492, cu sprijinul reginei Spaniei. În octombrie 1492 a ajuns pe o insulă din arhipelagul Bahamas. Au urmat alte trei expediții, în care a descoperit alte insule.",
