const flat = [];

U.forEach((u, ui) => u.topics.forEach((t, ti) => flat.push({ u, ui, t, i: flat.length })));

const $ = id => document.getElementById(id), list = $('list'), view = $('view');

const esc = s => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

function buildList(f) {
  list.innerHTML = '';
  U.forEach((u, ui) => {
    const items = flat.filter(x => x.ui === ui && (!f || x.t.t.toLowerCase().includes(f)));
    if (!items.length)
      return;
    const d = document.createElement('details');
    if (f)
      d.open = true;
    d.innerHTML = `<summary><span>${esc(u.n)}<small>${esc(u.t)}</small></span></summary>`;
    items.forEach(x => {
      const b = document.createElement('button');
      b.className = 't';
      b.dataset.i = x.i;
      b.textContent = x.t.t;
      b.onclick = () => show(x.i);
      d.appendChild(b);
    });
    list.appendChild(d);
  });
}

function home() {
  document.body.classList.remove('open');
  view.innerHTML = `<section class="home"><img src="${COVER}" alt="Coperta manualului Istoria românilor și universală, clasa a X-a"><h1>Temele la istorie clasa a X-a explicate pe scurt</h1><p>Alege o temă din lista din stânga și citește rezumatul ei. Sunt ${flat.length} teme și 10 unități/capitole.</p><button class="btn" id="go">Începe cu prima temă</button><p class="credit">Created by Pavel Viscun</p></section>`;
  $('go').onclick = () => show(0);
  document.querySelectorAll('.t.on').forEach(e => e.classList.remove('on'));
  $('main').scrollTop = 0;
}

function show(i) {
  const x = flat[i];
  view.innerHTML = `<article class="card"><p class="u">${esc(x.u.n)}. ${esc(x.u.t)}</p><h1>${esc(x.t.t)}</h1><p class="txt">${esc(x.t.p)}</p><div id="quiz" class="quiz"></div></article><div class="nav"><button class="btn" id="pv" ${i ? '' : 'disabled'}>← Înapoi</button><button class="btn" id="nx" ${i < flat.length - 1 ? '' : 'disabled'}>Următoarea →</button></div>`;
  quiz(i);
  mcq(i);
  tf(i);
  $('pv').onclick = () => show(i - 1);
  $('nx').onclick = () => show(i + 1);
  document.querySelectorAll('.t.on').forEach(e => e.classList.remove('on'));
  const b = list.querySelector(`.t[data-i="${i}"]`);
  if (b) {
    b.classList.add('on');
    const d = b.closest('details');
    if (d)
      d.open = true;
  }
  document.body.classList.remove('open');
  $('main').scrollTop = 0;
}

$('q').oninput = e => {
  buildList(e.target.value.trim().toLowerCase());
};

$('menu').onclick = () => document.body.classList.toggle('open');

$('hm').onclick = home;

buildList('');

home();

const RE = /^\d+( î\.H\.)?$/;

const shuf = a => a.map(v => [Math.random(), v]).sort((p, q) => p[0] - q[0]).map(p => p[1]);

function quiz(i) {
  const x = flat[i], [qs, ans] = x.t.q, num = RE.test(ans), bc = ans.includes('î.H.'), val = parseInt(ans);
  const all = flat.filter(o => o.i !== i).map(o => [o.t.q[1], o.ui === x.ui]).filter(o => o[0] !== ans);
  let d;
  if (num) {
    d = shuf(all.map(o => o[0]).filter(a => RE.test(a) && a.includes('î.H.') === bc).sort((a, b) => Math.abs(parseInt(a) - val) - Math.abs(parseInt(b) - val)).slice(0, 6));
  }
  else {
    const t = all.filter(o => !RE.test(o[0]));
    d = [...new Set(shuf(t.filter(o => o[1]).map(o => o[0])).concat(shuf(t.filter(o => !o[1]).map(o => o[0]))))];
  }
  const opts = shuf([ans, ...d.slice(0, 3)]), box = $('quiz'), btns = [];
  box.innerHTML = '<h2>Test</h2><p class="qq">' + esc(qs) + '</p>';
  opts.forEach(o => {
    const b = document.createElement('button');
    b.className = 'opt';
    b.textContent = o;
    btns.push(b);
    b.onclick = () => {
      // doar butoanele acestei întrebări (nu și grilele / adevărat-fals de dedesubt)
      btns.forEach(e => {
        e.disabled = true;
        if (e.textContent === ans)
          e.classList.add('ok');
      });
      const ok = o === ans;
      if (!ok)
        b.classList.add('bad');
      fb.textContent = ok ? 'Corect!' : 'Greșit. Răspunsul corect este: ' + ans;
    };
    box.appendChild(b);
  });
  const fb = document.createElement('p');
  fb.className = 'fb';
  box.appendChild(fb);
}

function tf(i) {
  const f = flat[i].t.f, box = $('quiz');
  if (!f || !f.length)
    return;
  const h = document.createElement('h2');
  h.className = 'tfh';
  h.textContent = 'Adevărat sau fals?';
  box.appendChild(h);
  let done = 0, score = 0;
  const res = document.createElement('p');
  res.className = 'fb';
  shuf(f).forEach(([txt, val]) => {
    const w = document.createElement('div');
    w.className = 'tfq';
    const p = document.createElement('p');
    p.className = 'qq';
    p.textContent = txt;
    w.appendChild(p);
    const r = document.createElement('div');
    r.className = 'tfr';
    const m = document.createElement('p');
    m.className = 'fb';
    [['Adevărat', true], ['Fals', false]].forEach(([lb, v]) => {
      const b = document.createElement('button');
      b.className = 'opt tfb';
      b.textContent = lb;
      b.onclick = () => {
        r.querySelectorAll('.opt').forEach(e => {
          e.disabled = true;
          if ((e.textContent === 'Adevărat') === val)
            e.classList.add('ok');
        });
        const ok = v === val;
        if (!ok)
          b.classList.add('bad');
        else
          score++;
        m.textContent = ok ? 'Corect!' : 'Greșit. Afirmația este ' + (val ? 'adevărată.' : 'falsă.');
        if (++done === f.length) {
          res.textContent = 'Scor la adevărat/fals: ' + score + ' din ' + f.length + '.';
        }
      };
      r.appendChild(b);
    });
    w.appendChild(r);
    w.appendChild(m);
    box.appendChild(w);
  });
  box.appendChild(res);
}

function mcq(i) {
  const ms = flat[i].t.m, box = $('quiz');
  if (!ms || !ms.length)
    return;
  ms.forEach(([qs, ans, ...d]) => {
    const w = document.createElement('div');
    w.className = 'mq';
    const p = document.createElement('p');
    p.className = 'qq';
    p.textContent = qs;
    w.appendChild(p);
    const fb = document.createElement('p');
    fb.className = 'fb';
    shuf([ans, ...d]).forEach(o => {
      const b = document.createElement('button');
      b.className = 'opt';
      b.textContent = o;
      b.onclick = () => {
        w.querySelectorAll('.opt').forEach(e => {
          e.disabled = true;
          if (e.textContent === ans)
            e.classList.add('ok');
        });
        const ok = o === ans;
        if (!ok)
          b.classList.add('bad');
        fb.textContent = ok ? 'Corect!' : 'Greșit. Răspunsul corect este: ' + ans;
      };
      w.appendChild(b);
    });
    w.appendChild(fb);
    box.appendChild(w);
  });
}